/**
 * @name Taint from parse_obj to pickle.loads
 * @description Track data from pydantic.parse_obj or BaseModel.parse_obj into pickle.loads
 * @kind path-problem
 * @problem.severity error
 * @id py/pydantic/taint-parseobj-to-pickle
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

module ParseToPickleConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(API::CallNode c |
      c = API::moduleImport("pydantic").getMember("parse_obj_as").getACall() or
      c = API::moduleImport("pydantic.main").getMember("BaseModel").getMember("parse_obj").getACall() |
      source = c.getArg(0)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode c |
      c = API::moduleImport("pickle").getMember("loads").getACall() |
      sink = c.getArg(0)
    )
  }
}

module ParseToPickleFlow = TaintTracking::Global<ParseToPickleConfig>;
import ParseToPickleFlow::PathGraph

from ParseToPickleFlow::PathNode source, ParseToPickleFlow::PathNode sink
where ParseToPickleFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Data from pydantic parsing flows into pickle.loads here.", source, "pydantic input"

/**
 * @name Untrusted data to eval/exec in pydantic
 * @description Track data from pydantic parsing helpers into eval/exec
 * @kind path-problem
 * @problem.severity error
 * @id py/pydantic/taint-parseobj-to-eval
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

module ParseToEvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(API::CallNode c |
      c = API::moduleImport("pydantic").getMember("parse_obj_as").getACall() or
      c = API::moduleImport("pydantic.main").getMember("BaseModel").getMember("parse_obj").getACall() |
      source = c.getArg(0)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode c |
      c = API::builtin(["eval", "exec"]).getACall() |
      sink = c.getArg(0)
    )
  }
}

module ParseToEvalFlow = TaintTracking::Global<ParseToEvalConfig>;
import ParseToEvalFlow::PathGraph

from ParseToEvalFlow::PathNode source, ParseToEvalFlow::PathNode sink
where ParseToEvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Data from pydantic parsing flows into eval/exec here.", source.getNode(), "pydantic input"
